const app=document.querySelector('#app');
let archive,activeIndex=0,slideIndex=0,filmstrip=null,lastProject=null,photoObserver=null,activeFilter='Todas';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>String(n).padStart(2,'0');
const reference=p=>archive.references.find(r=>r.id===p.referenceId);
const safeUrl=s=>{if(!s)return '#';try{const u=new URL(s,location.href);const isRelative=!/^[a-z][a-z\d+.-]*:/i.test(s)&&!s.startsWith('//');return ['http:','https:'].includes(u.protocol)||isRelative?escape(s):'#'}catch{return '#'}};
const likeIcon='<svg viewBox="0 0 18 18" aria-hidden="true"><path d="M9 15.1 2.7 9.2A3.75 3.75 0 0 1 8 3.9L9 4.8l1-.9a3.75 3.75 0 0 1 5.3 5.3Z"/></svg>';
const CardLike=(p)=>`<div class="card-like-shell" data-card-likes="${escape(p.id)}" aria-live="polite"></div>`;
function SiteHeader(view){return `<header class="site-header"><a class="wordmark" href="#" aria-label="Szymon Keller — índice">Szymon Keller</a><nav class="site-nav" aria-label="Navegación principal"><a href="#" ${view==='index'?'aria-current="page"':''}>Índice</a><a href="#briefing" ${view==='briefing'?'aria-current="page"':''}>Briefing</a><a href="#fuentes" ${view==='sources'?'aria-current="page"':''}>Fuentes y notas</a></nav></header>`}
function ProjectStack(p,i,visible=true){const r=reference(p);const layers=Array.from({length:3},(_,j)=>p.images[j%p.images.length]);return `<article class="project-tile${visible?'':' is-filtered-out'}" data-stack-id="${escape(p.id)}"><a class="project-card" href="#proyecto/${escape(p.id)}" aria-label="${escape(r.name)} — ${escape(p.title)}" ${visible?'':'aria-hidden="true" tabindex="-1"'}><span class="card-number">${number(i+1)}</span><span class="image-stack" aria-hidden="true">${layers.slice().reverse().map((im,k)=>`<img class="stack-image${k===layers.length-1?' front-image':''}" style="--layer:${layers.length-k-1}" src="${safeUrl(im.src)}" alt="" loading="${i<8?'eager':'lazy'}">`).join('')}</span><dl class="card-meta"><dt>ROLE</dt><dd>${escape(p.role)}</dd><dt>NAME</dt><dd>${escape(r.name)}</dd><dt>PROJECT</dt><dd>${escape(p.title)}</dd></dl></a>${CardLike(p)}</article>`}
const filters=['Todas','Iluminación','Bodegón','Exterior','Proporción','Materialidad','Catálogo','Escenografía'];
function FilterSidebar(){return `<aside class="filter-sidebar" aria-label="Categorías de investigación"><div class="filter-list">${filters.map(f=>`<button class="filter-button" data-filter="${escape(f)}" aria-pressed="${activeFilter===f}">${escape(f)}</button>`).join('')}</div></aside>`}
function Index(){const matching=p=>activeFilter==='Todas'||p.categories?.includes(activeFilter);const total=archive.projects.filter(matching).length;const countText=activeFilter==='Todas'?`${number(archive.projects.length)} proyectos · ${number(archive.references.length)} referentes`:`${number(total)} de ${number(archive.projects.length)} proyectos · ${escape(activeFilter)}`;return `${SiteHeader('index')}<main id="main"><div class="index-intro"><p>Archivo de investigación <span class="muted">/ Dirección de arte</span></p><p>${countText}<span class="likes-total" data-likes-total></span></p></div><div class="index-archive">${FilterSidebar()}<div class="project-grid">${archive.projects.map((p,i)=>ProjectStack(p,i,matching(p))).join('')}</div></div></main><footer class="index-footer"><span>Brain behind site: Rodrigo Meiriño</span></footer>`}
function SourceCredit(im){return `<div><p>${escape(im.caption)}</p><p class="credit">${escape(im.credit)}</p><a href="${safeUrl(im.source)}" target="_blank" rel="noopener noreferrer">Fuente original ↗</a></div>`}
function Annotation(a){return `<div class="annotation"><span class="annotation-number" aria-hidden="true">${escape(a.number)}</span><p>${escape(a.text)}</p></div>`}
function ImagePlate(im,i){return `<figure class="image-plate" id="imagen-${i+1}" aria-label="Imagen ${i+1}: ${escape(im.alt)}"><div class="photo-field"><img src="${safeUrl(im.src)}" alt="${escape(im.alt)}" ${i>1?'loading="lazy"':''}><span class="image-marker" data-x="${im.annotations[0]?.position?.x??.1}" data-y="${im.annotations[0]?.position?.y??.1}" aria-hidden="true">${number(i+1)}</span></div><figcaption class="plate-caption">${SourceCredit(im)}<div>${im.annotations.map(a=>Annotation({...a,number:number(i+1)})).join('')}</div></figcaption></figure>`}
function ProjectNavigation(p){const next=archive.projects[(activeIndex+1)%archive.projects.length];return `<footer class="detail-footer"><p class="help">Recorrer imágenes con ← → · Esc vuelve al índice</p><div class="slide-controls"><button id="previous-image" aria-label="Imagen anterior">←</button><span id="slide-count" aria-live="polite">01 / ${number(p.images.length)}</span><button id="next-image" aria-label="Imagen siguiente">→</button></div><a class="next-project" href="#proyecto/${escape(next.id)}">${activeIndex===archive.projects.length-1?'Volver al primer proyecto':'Siguiente proyecto'} ↗</a></footer>`}
function ProjectDetail(p){const r=reference(p);const related=archive.projects.filter(x=>x.referenceId===p.referenceId&&x.id!==p.id);return `${SiteHeader('detail')}<main id="main"><div class="detail-heading"><div><p class="eyebrow">${number(activeIndex+1)} / ${escape(p.role)}${p.context?` / ${escape(p.context)}`:''}</p><h1 tabindex="-1">${escape(p.title)}</h1><p class="project-byline">${escape(r.name)}</p></div><div class="detail-actions"><span class="detail-count">${number(p.images.length)} ${p.images.length===1?'imagen':'imágenes'}</span><div class="project-like-shell" data-project-likes aria-live="polite"></div></div></div><div class="detail-stage"><aside class="editorial" aria-label="Notas editoriales"><section class="editorial-block"><h2>OPERACIÓN VISUAL</h2><p>${escape(p.operation)}</p></section><section class="editorial-block application"><h2>PARA SZYMON / PROPUESTA</h2><p>${escape(p.application)}</p></section><section class="fixed-note"><h2>NOTA DE PARTIDA</h2><p>${escape(r.fixedNote)}</p></section>${related.length?`<div class="cross-references"><p>Lecturas cruzadas / ${escape(r.name)}</p>${related.map(x=>`<a href="#proyecto/${escape(x.id)}">${escape(x.title)} ↗</a>`).join('')}</div>`:''}<a class="research-link" href="${safeUrl(p.source)}" target="_blank" rel="noopener noreferrer">Consultar el proyecto original ↗</a></aside><div class="filmstrip" tabindex="0" aria-label="Secuencia horizontal de imágenes">${p.images.map(ImagePlate).join('')}</div></div></main>${ProjectNavigation(p)}`}
function Briefing(){return `${SiteHeader('briefing')}<main id="main" class="briefing-page"><div class="briefing-heading"><p class="eyebrow">Preparación de reunión</p><h1>Briefing</h1><p>Preguntas para entender el proyecto, la audiencia y el papel de las nuevas imágenes.</p></div><section class="briefing-section"><span class="briefing-number">01</span><div><h2>Entender el proyecto</h2><ul><li>¿Qué piezas quieren fotografiar?</li><li>¿Qué lanzamientos vienen?</li><li>¿Para qué necesitan las imágenes: web, prensa, Instagram o catálogo?</li></ul></div></section><section class="briefing-section"><span class="briefing-number">02</span><div><h2>Audiencia</h2><p>En estrategia, la audiencia es el centro de la comunicación.</p><ul><li>¿A quién queremos enamorar?</li><li>¿Hay un público prioritario?</li><li>¿Hay algún antecedente de comunicación del que quieran hablar? ¿Qué resultado tuvo?</li></ul><p class="briefing-example">Ejemplos: interioristas, arquitectos, prensa, cliente final y casas de decoración.</p></div></section><section class="briefing-section"><span class="briefing-number">03</span><div><h2>Problema actual</h2><p class="briefing-quote">«La foto no transmite lo mismo que la pieza en persona».</p><ul><li>¿Qué se pierde?<ul><li>Transparencia y profundidad.</li><li>Textura.</li><li>Proporción y escala.</li><li>Reflejos y relación con la luz.</li><li>Color.</li><li>Sensación física: tacto y peso.</li></ul></li><li>¿Qué imágenes anteriores no funcionan y cuáles sí?</li><li>Cuando hay alguien delante de una pieza, ¿qué hace instintivamente? ¿Cómo interactúa?</li><li>Cuando dicen «en la foto no se entiende», ¿qué palabra utilizan después? Por ejemplo: «es más luminosa», «es más liviana» o «es más pequeña».</li></ul></div></section><section class="briefing-section"><span class="briefing-number">04</span><div><h2>Objetivo</h2><ul><li>¿Qué debería conseguir la nueva fotografía?</li></ul><p>Por ejemplo:</p><ul class="briefing-examples"><li>Hacer comprensible el material.</li><li>Transmitir la experiencia física.</li><li>Dar más valor o percepción de pieza artística y coleccionable.</li><li>¿Se quiere documentar el objeto o crear a su alrededor un universo reconocible de Szymon?</li></ul></div></section></main>`}
function Sources(){return `${SiteHeader('sources')}<main id="main" class="sources-page"><h1>Fuentes y notas</h1><p class="sources-lead">Las notas de partida recogen los criterios de esta reunión. Las operaciones visuales son lecturas editoriales; las aplicaciones a Szymon, propuestas para conversar. La selección reúne fuentes aportadas por Rodrigo y páginas originales enlazadas en cada ficha.</p>${archive.references.map((r,i)=>{const projects=archive.projects.filter(p=>p.referenceId===r.id);return `<section class="source-record"><span class="muted">${number(i+1)}</span><h2>${escape(r.name)}</h2><div><p>${escape(r.fixedNote)}</p><div class="source-links">${projects.map(p=>`<a href="#proyecto/${escape(p.id)}">${escape(p.title)}</a>`).join('')}</div></div></section>`}).join('')}</main>`}
function goSlide(delta){if(!filmstrip)return;const plates=[...filmstrip.querySelectorAll('.image-plate')];const target=Math.max(0,Math.min(plates.length-1,slideIndex+delta));filmstrip.scrollTo({left:plates[target].offsetLeft-plates[0].offsetLeft,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function updateSlide(){if(!filmstrip)return;const plates=[...filmstrip.querySelectorAll('.image-plate')];const step=plates.length>1?plates[1].offsetLeft-plates[0].offsetLeft:1;slideIndex=Math.min(plates.length-1,Math.max(0,Math.round(filmstrip.scrollLeft/step)));document.querySelector('#slide-count').textContent=`${number(slideIndex+1)} / ${number(plates.length)}`;document.querySelector('#previous-image').disabled=slideIndex===0;document.querySelector('#next-image').disabled=slideIndex===plates.length-1}
function attachStackPreviews(){
  const supportsPreview=matchMedia('(hover:hover)').matches&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(!supportsPreview)return;
  document.querySelectorAll('[data-stack-id]').forEach(tile=>{
    const project=archive.projects.find(p=>p.id===tile.dataset.stackId);
    if(!project)return;
    let [back,middle,front]=[...tile.querySelectorAll('.stack-image')];
    if(!back||!middle||!front)return;
    let revealTimer,advanceTimer,nextImage=3;
    const setLayer=(image,layer)=>{image.style.setProperty('--layer',layer);image.style.zIndex=String(3-layer)};
    const reset=()=>{
      [back,middle,front].forEach(image=>image.classList.remove('is-fading','front-image'));
      back.src=safeUrl(project.images[2%project.images.length].src);
      middle.src=safeUrl(project.images[1%project.images.length].src);
      front.src=safeUrl(project.images[0].src);
      setLayer(back,2);setLayer(middle,1);setLayer(front,0);front.classList.add('front-image');nextImage=3;
    };
    const clear=()=>{clearTimeout(revealTimer);clearTimeout(advanceTimer)};
    const advance=()=>{
      front.classList.add('is-fading');
      advanceTimer=setTimeout(()=>{
        const outgoing=front;
        outgoing.src=safeUrl(project.images[nextImage%project.images.length].src);
        nextImage+=1;
        outgoing.classList.remove('front-image');
        setLayer(middle,0);setLayer(back,1);setLayer(outgoing,2);
        middle.classList.add('front-image');
        [front,middle,back]=[middle,back,outgoing];
        requestAnimationFrame(()=>outgoing.classList.remove('is-fading'));
        revealTimer=setTimeout(advance,1800);
      },480);
    };
    const start=()=>{clear();reset();revealTimer=setTimeout(advance,500)};
    const stop=()=>{clear();reset()};
    tile.addEventListener('pointerenter',start);
    tile.addEventListener('pointerleave',stop);
    tile.addEventListener('focusin',start);
    tile.addEventListener('focusout',stop);
  });
}
function positionMarkers(){document.querySelectorAll(".photo-field").forEach(field=>{const img=field.querySelector("img"),marker=field.querySelector(".image-marker");if(!img||!marker||!img.naturalWidth)return;const scale=Math.min(field.clientWidth/img.naturalWidth,field.clientHeight/img.naturalHeight),w=img.naturalWidth*scale,h=img.naturalHeight*scale;marker.style.left=((field.clientWidth-w)/2+w*Number(marker.dataset.x))+"px";marker.style.top=((field.clientHeight-h)/2+h*Number(marker.dataset.y))+"px"})}
function render(){photoObserver?.disconnect();const hash=location.hash;filmstrip=null;slideIndex=0;if(hash.startsWith('#proyecto/')){const id=hash.slice(10);activeIndex=archive.projects.findIndex(p=>p.id===id);if(activeIndex<0){app.innerHTML=`${SiteHeader('')}<main class="fatal"><h1>Este proyecto no está en el archivo.</h1><a href="#">Volver al índice</a></main>`;return}const p=archive.projects[activeIndex];lastProject=p.id;app.innerHTML=ProjectDetail(p);document.title=`${p.title} — Szymon Keller`;filmstrip=document.querySelector('.filmstrip');filmstrip.addEventListener('scroll',updateSlide,{passive:true});document.querySelector('#previous-image').onclick=()=>goSlide(-1);document.querySelector('#next-image').onclick=()=>goSlide(1);updateSlide();window.initialiseProjectLikes?.(p);document.querySelector('h1').focus({preventScroll:true})}else if(hash==='#briefing'){app.innerHTML=Briefing();document.title='Briefing — Szymon Keller'}else if(hash==='#fuentes'){app.innerHTML=Sources();document.title='Fuentes y notas — Szymon Keller'}else{app.innerHTML=Index();document.title='Szymon Keller — Referencias';document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{activeFilter=button.dataset.filter;render()}));window.initialiseIndexLikes?.(archive.projects);attachStackPreviews();if(lastProject)document.querySelector(`a[href="#proyecto/${lastProject}"]`)?.focus({preventScroll:true})}window.scrollTo(0,0);photoObserver=new ResizeObserver(positionMarkers);document.querySelectorAll(".photo-field").forEach(field=>photoObserver.observe(field));document.querySelectorAll(".photo-field img").forEach(img=>img.addEventListener("load",positionMarkers));positionMarkers();document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{if(img.closest('.photo-field')){const message=document.createElement('p');message.className='image-unavailable';message.textContent='Imagen no disponible. Consultá la fuente original en el pie.';img.replaceWith(message)}else{img.style.visibility='hidden'}},{once:true}))}
window.addEventListener('hashchange',()=>{if(archive)render()});window.addEventListener('keydown',e=>{if(!filmstrip||e.altKey||e.metaKey||e.ctrlKey)return;if(e.key==='ArrowRight'){e.preventDefault();goSlide(1)}if(e.key==='ArrowLeft'){e.preventDefault();goSlide(-1)}if(e.key==='Escape'){location.hash=''}});
try{const response=await fetch('data/references.json?v=20260914-v27');if(!response.ok)throw Error('Archive unavailable');archive=await response.json();render()}catch{app.innerHTML='<main class="fatal"><h1>No se pudo abrir el archivo.</h1><p>Recargá la página para volver a intentarlo.</p></main>'}
